using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    while (cin >> n && n != 0) {
        vector<double> x(n), y(n);
        for (int i = 0; i < n; i++) {
            cin >> x[i] >> y[i];
        }

        if (n % 2 != 0) {
            cout << "NA" << endl;
            continue;
        }

        int half = n / 2;
        double cx = (x[0] + x[half]) / 2.0;
        double cy = (y[0] + y[half]) / 2.0;

