int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    vector<Point> p(N);
    for (int i = 0; i < N; ++i) cin >> p[i].x >> p[i].y;

    // For any planar figure, a point through which every line bisects the area
    // must be the center of central symmetry of the figure.
    // For a convex polygon, this exists iff the polygon is centrally symmetric.
    //
    // In that case, for all i:
    // p[i] + p[i + N/2] = constant (indices modulo N)
    // Therefore N must be even.

    if (N % 2 == 1) {
        cout << "NA\n";
        return 0;
    }

    const long double EPS = 1e-10;

    long double sx = p[0].x + p[N / 2].x;
    long double sy = p[0].y + p[N / 2].y;

    for (int i = 1; i < N / 2; ++i) {
        long double tx = p[i].x + p[i + N / 2].x;
        long double ty = p[i].y + p[i + N / 2].y;
        if (fabsl(tx - sx) > EPS || fabsl(ty - sy) > EPS) {
            cout << "NA\n";
            return 0;
        }
    }

    long double cx = sx / 2.0L;
    long double cy = sy / 2.0L;

    cout << fixed << setprecision(10) << (double)cx << ' ' << (double)cy << '\n';
    return 0;
}

