#include <stdio.h>
#include <math.h>

typedef struct {
    double x, y;
} Point;

static const double EPS = 1e-9;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Point p[200005];
    for (int i = 0; i < N; i++) {
        scanf("%lf %lf", &p[i].x, &p[i].y);
    }

    /*
      For a convex polygon, a point through which every line bisects the area
      exists iff the polygon is centrally symmetric. In that case, the point is
      the center of symmetry, equivalently the centroid of area-bisecting lines,
      and for vertices listed cyclically:
          p[i] + p[i + N/2] = constant
      for all i, which requires N even.

      Then the common midpoint is the answer.
    */

    if (N % 2 == 1) {
        printf("NA\n");
        return 0;
    }

    double sx = p[0].x + p[N / 2].x;
    double sy = p[0].y + p[N / 2].y;

    for (int i = 1; i < N / 2; i++) {
        double tx = p[i].x + p[i + N / 2].x;
        double ty = p[i].y + p[i + N / 2].y;
        if (fabs(tx - sx) > EPS || fabs(ty - sy) > EPS) {
            printf("NA\n");
            return 0;
        }
    }

    printf("%.10f %.10f\n", sx / 2.0, sy / 2.0);
    return 0;
}

