            y[i] = sc.nextDouble();
        }

        if (n % 2 != 0) {
            System.out.println("NA");
            return;
        }

        // Candidate center: midpoint of vertex 0 and vertex n/2
        double cx = (x[0] + x[n/2]) / 2.0;
        double cy = (y[0] + y[n/2]) / 2.0;

        // Check all pairs
        double eps = 1e-9;
        boolean valid = true;
        for (int i = 0; i < n/2; i++) {
            int j = i + n/2;
            double midX = (x[i] + x[j]) / 2.0;
            double midY = (y[i] + y[j]) / 2.0;
            if (Math.abs(midX - cx) > eps || Math.abs(midY - cy) > eps) {
                valid = false;
                break;
            }
        }

        if (valid) {
            System.out.println(cx + " " + cy);
        } else {
            System.out.println("NA");
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        double[] x = new double[N];
        double[] y = new double[N];

        for (int i = 0; i < N; i++) {
            x[i] = sc.nextDouble();
            y[i] = sc.nextDouble();
        }

        double area = 0.0;
        double cx = 0.0, cy = 0.0;

        for (int i = 0; i < N; i++) {
            int j = (i + 1) % N;
            double cross = x[i] * y[j] - x[j] * y[i];
            area += cross;
            cx += (x[i] + x[j]) * cross;
            cy += (y[i] + y[j]) * cross;
        }

        area /= 2.0;

        if (Math.abs(area) < 1e-12) {
            System.out.println("NA");
            return;
        }

        cx /= (6.0 * area);
        cy /= (6.0 * area);

        System.out.printf("%.6f %.6f%n", cx, cy);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        Point[] p = new Point[N];
        long[] xs = new long[N];
        long[] ys = new long[N];
        for (int i = 0; i < N; i++) {
            xs[i] = fs.nextLong();
            ys[i] = fs.nextLong();
            p[i] = new Point(xs[i], ys[i]);
        }

        if ((N & 1) == 0) {
            // For a convex polygon, such a point exists iff polygon is centrally symmetric.
            int m = N / 2;
            long sx = xs[0] + xs[m];
            long sy = ys[0] + ys[m];
            boolean ok = true;
            for (int i = 1; i < m; i++) {
                if (xs[i] + xs[i + m] != sx || ys[i] + ys[i + m] != sy) {
                    ok = false;
                    break;
                }
            }
            if (!ok) {
                System.out.println("NA");
                return;
            }
            printNumber(sx / 2.0);
            System.out.print(" ");
            printNumber(sy / 2.0);
            System.out.println();
        } else {
            // No centrally symmetric polygon can have odd number of vertices.
            System.out.println("NA");
        }
    }

    static void printNumber(double v) {
        if (Math.abs(v - Math.rint(v)) < 1e-9) {
            System.out.print((long) Math.rint(v));
        } else {
            System.out.print(String.format(Locale.US, "%.10f", v).replaceAll("0+$", "").replaceAll("\\.$", ""));
        }
    }
}
